  var A_REGIONS = [["sw", "Statewide"], ["ev", "East Valley"], ["cn", "Central & North Phoenix"], ["wv", "West Valley"], ["tu", "Tucson & Southern AZ"], ["no", "Northern AZ"], ["yu", "Yuma"]];
